import{_ as t,o as a,c as s,a0 as o}from"./chunks/framework.BxCN1dRw.js";const u=JSON.parse('{"title":"Walkthrough: Backing up and restoring documents, attachments and jobs in an isolated environment","description":"","frontmatter":{"docLocale":"en","counterpart":"/tutorials/backup-restore"},"headers":[],"relativePath":"en/tutorials/backup-restore.md","filePath":"en/tutorials/backup-restore.md"}'),n={name:"en/tutorials/backup-restore.md"};function i(r,e,d,c,h,p){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="walkthrough-backing-up-and-restoring-documents-attachments-and-jobs-in-an-isolated-environment" tabindex="-1">Walkthrough: Backing up and restoring documents, attachments and jobs in an isolated environment <a class="header-anchor" href="#walkthrough-backing-up-and-restoring-documents-attachments-and-jobs-in-an-isolated-environment" aria-label="Permalink to &quot;Walkthrough: Backing up and restoring documents, attachments and jobs in an isolated environment&quot;">​</a></h1><p>This chapter answers &quot;how production data is backed up and how restorability is proven&quot;. A backup is not &quot;copying the volume directory&quot; — it is an auditable process: inside a maintenance window new changes are stopped and in-flight requests are drained, the database gets a consistent snapshot, and every ready object is verified against the database registry. A restore always enters an isolated empty environment rebuilt from the archive plus protected configuration, and then a real API journey proves that accounts, documents, attachments and queued jobs all came back. Two operations commands (<code>production-backup</code>, <code>production-restore</code>) cover daily use, and the <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/957a0b05c2cb3d0ed820d65a99a561cbb86fffd8/scripts/production-restore-drill.mjs" target="_blank" rel="noreferrer">automated drill</a> turns the whole &quot;backup → restore → verify&quot; chain into one command that generates fresh secrets, a random project name and fresh data on every run.</p><h2 id="_1-what-the-backup-contains-—-and-what-it-does-not" tabindex="-1">1. What the backup contains — and what it does not <a class="header-anchor" href="#_1-what-the-backup-contains-—-and-what-it-does-not" aria-label="Permalink to &quot;1. What the backup contains — and what it does not&quot;">​</a></h2><p>The archive produced by <code>just production-backup</code> = database snapshot + object manifest + manifest-verified object bytes + report:</p><table tabindex="0"><thead><tr><th>Archive content</th><th>Form</th></tr></thead><tbody><tr><td><code>database.dump</code></td><td><code>pg_dump -Fc</code> custom format including <code>_sqlx_migrations</code>, restorable across versions with <code>pg_restore</code></td></tr><tr><td><code>manifest.json</code></td><td>Application image and digest, migration version and count, <code>sha256</code> and size of every ready file</td></tr><tr><td><code>objects/</code></td><td>The exact bytes of every ready object in the manifest, written to disk only after a per-object digest check against the database</td></tr><tr><td><code>backup-report.md</code></td><td>PASS/FAIL verdict with check details, for human review</td></tr></tbody></table><p>Registering only ready objects is by design: ready objects are immutable and their content digest lives in the database (<code>saas_core.files.sha256</code>), so &quot;database snapshot + ready objects&quot; forms one self-consistent point — manifest and snapshot corroborate each other, and anything missing on either side is detectable (extra objects are reported but do not fail the backup, such as staging keys not yet cleaned up). Staging objects of pending uploads are not in the backup: after a restore they expire by TTL and are cleaned up idempotently — exactly the behavior the drill verifies.</p><p>Secrets are not in the archive. <code>POSTGRES_PASSWORD</code>, <code>S3_*</code> and <code>MAIL_ENCRYPTION_KEY</code> belong to the protected configuration and are provided separately from the deployer&#39;s environment file at restore time — losing the archive leaks no secrets, and holding only the archive without the environment file does not open the database. Archive and secrets are stored and authorized separately (the local Caddy root CA could likewise issue entry certificates; the script writes it only to a temporary directory and never into the archive).</p><h2 id="_2-the-maintenance-window-stop-changes-drain-snapshot" tabindex="-1">2. The maintenance window: stop changes, drain, snapshot <a class="header-anchor" href="#_2-the-maintenance-window-stop-changes-drain-snapshot" aria-label="Permalink to &quot;2. The maintenance window: stop changes, drain, snapshot&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production-backup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ENV_FILE=.env.production</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # The archive lands in backups/&lt;timestamp&gt;/</span></span></code></pre></div><p>The <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/957a0b05c2cb3d0ed820d65a99a561cbb86fffd8/scripts/production-backup.mjs" target="_blank" rel="noreferrer">backup script</a> runs the full window sequence with a stopwatch: first the API stops (no new mutations; 30s grace period; the logs must contain <code>draining HTTP requests</code>), then the Worker stops (in-flight claims finish; 45s grace period; the logs must contain <code>stopping worker claims and draining current work</code>). If either reaches compose&#39;s kill grace period instead of exiting by itself, the script fails immediately. Only with both writers stopped is what <code>pg_dump</code> receives a consistent point free of new changes — the flip side of &quot;assume staging PUTs stopped without stopping the API&quot; is that the drain must really happen. No new requests can enter during the window, while already-queued jobs (such as exports) stay in the database job table and are claimed and completed by the Worker after recovery — nothing is lost. The stack ends the backup stopped; a plain <code>just production-up</code> restarts it.</p><p>The object side needs no separate freeze: ready objects are immutable, the manifest is generated row by row from the database (<code>ready_key</code>, <code>sha256</code>, <code>actual_size</code> of <code>state = &#39;ready&#39;</code> rows) and then cross-checked against the bucket via ListObjectsV2 through the entry. Object operations are signed with the <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/957a0b05c2cb3d0ed820d65a99a561cbb86fffd8/scripts/lib/sigv4.mjs" target="_blank" rel="noreferrer">minimal SigV4 implementation</a> using <code>S3_PUBLIC_ENDPOINT</code> — the same path as presigned URLs, whose correctness is pinned byte-for-byte against the official AWS get-vanilla test vectors (<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/957a0b05c2cb3d0ed820d65a99a561cbb86fffd8/tests/tooling/backup-sigv4.test.mjs" target="_blank" rel="noreferrer">tests</a>); every object is also downloaded and compared against the database digest before it enters the archive.</p><h2 id="_3-restore-an-isolated-empty-environment-never-an-overwrite" tabindex="-1">3. Restore: an isolated empty environment, never an overwrite <a class="header-anchor" href="#_3-restore-an-isolated-empty-environment-never-an-overwrite" aria-label="Permalink to &quot;3. Restore: an isolated empty environment, never an overwrite&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production-restore</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ARCHIVE=backups/20260927-120000</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ENV_FILE=.env.production</span></span></code></pre></div><p>The <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/957a0b05c2cb3d0ed820d65a99a561cbb86fffd8/scripts/production-restore.mjs" target="_blank" rel="noreferrer">restore script</a> targets an isolated environment by default: a different compose project name (default <code>axum-saas-production-restore-&lt;timestamp&gt;</code>), with network and volumes all newly created. The script refuses outright when the project name matches production — same name means same volumes, the one overwrite path. It publishes the same ports as production, so the production composition must be fully stopped first; replacing it requires an explicit <code>down -v</code> of the old environment, and that decision is always a human&#39;s. The script then: starts dependencies → <code>pg_restore --no-owner --exit-on-error</code> (a half-restored database never passes silently) → <code>storage-init</code> creates the bucket → starts the entry (object PUTs must pass through Caddy for signatures to be valid) → signed-PUTs every file from <code>objects/</code> back into the bucket per <code>manifest.json</code> → starts the app → structural verification (readiness, migration versions matching the manifest, bucket contents matching the manifest). The restore report lands in the archive and the restored stack keeps running for human inspection. The app never migrates or creates buckets implicitly — the restore environment obeys the same contract as a first deployment.</p><h2 id="_4-the-drill-automated-proof-that-this-archive-really-restores" tabindex="-1">4. The drill: automated proof that this archive really restores <a class="header-anchor" href="#_4-the-drill-automated-proof-that-this-archive-really-restores" aria-label="Permalink to &quot;4. The drill: automated proof that this archive really restores&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production-restore-drill</span></span></code></pre></div><p>The <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/957a0b05c2cb3d0ed820d65a99a561cbb86fffd8/scripts/production-restore-drill.mjs" target="_blank" rel="noreferrer">drill script</a> builds its own images and generates its own secrets and environment file (mail configured but unreachable, telemetry endpoint down — degradation runs through the whole journey), then drives the same two commands from sections 2 and 3 through the full chain and appends journey assertions:</p><ol><li><strong>Seed</strong>: register an owner, write a document with known content, upload an attachment with known bytes and complete it, open one <strong>pending upload whose bytes never arrive</strong> as the expiry victim, then queue an export after stopping the Worker.</li><li><strong>Window and backup</strong>: <code>production-backup</code> drains and times the window, producing the dump, manifest, verified objects and backup report.</li><li><strong>Rebuild</strong>: the drill runs <code>down -v</code> on the production project to free the ports, then <code>production-restore</code> rebuilds the isolated project from the archive alone.</li><li><strong>Journey verification</strong>: the original session cookie still works (sessions live in the restored database); the document and attachment read back byte-for-byte; the queued export is completed by the restored Worker to <code>succeeded</code> with zip content identical to the source; the pending upload expires to the <code>expired</code> terminal state and <code>object_cleanup</code> records <code>first_deleted_at</code> for the staging key — the cleanup stays idempotent even though the object never existed; no job ends <code>failed</code>.</li><li><strong>Report</strong>: three reports stay in the archive (<code>drill-report.md</code>, <code>backup-report.md</code>, <code>restore-report.md</code>); any failure outside PASS ends the drill with a <code>[phase-name]</code> prefix.</li></ol><p>The upload TTL is 15 minutes (the <code>upload_secs</code> policy default), and the drill does not wait it out: it rewinds that row&#39;s <code>expires_at</code> into the past in the restored database, while the real maintenance sweep (30-second period) and cleanup job still perform the expiry, cleanup enqueue and idempotent deletion — the drill moves the clock, production code always runs the state machine.</p><p>The drill is repeatable: project names carry the PID, secrets are random, and it ends with <code>down -v</code> on both projects plus deleting the environment file and the temporary root CA; the archive stays under <code>.scratch/</code> for review (it contains only drill data). If ports 80/443 are taken, the production composition is still running — run <code>just production-down</code> first; that is the natural troubleshooting step of the &quot;restore never touches production&quot; constraint. The <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/957a0b05c2cb3d0ed820d65a99a561cbb86fffd8/tests/tooling/backup-manifest.test.mjs" target="_blank" rel="noreferrer">manifest logic tests</a> verify manifest normalization, verification semantics and report rendering without Docker.</p><h2 id="_5-run-this-chapter-s-checks" tabindex="-1">5. Run this chapter&#39;s checks <a class="header-anchor" href="#_5-run-this-chapter-s-checks" aria-label="Permalink to &quot;5. Run this chapter&#39;s checks&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/tooling/backup-sigv4.test.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/tooling/backup-manifest.test.mjs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production-restore-drill</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span></code></pre></div><p>Like single-machine production deployment, this chapter is a template core capability (Core) and is not registered in the example ownership manifest — the backup/restore tooling serves anyone deploying from the template and is not removed with the example business. Backup and restore are two halves of one tool: every drill run also proves &quot;this archive really restores&quot;, a stronger promise than &quot;the backup succeeded&quot;.</p><hr><p>Source version：<code>957a0b05c2cb</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/957a0b05c2cb3d0ed820d65a99a561cbb86fffd8/docs/tutorials/22-backup-restore.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,25)])])}const b=t(n,[["render",i]]);export{u as __pageData,b as default};
